#!/bin/bash
set -euo pipefail

LOG=/var/log/nginx/custom_access.log
OUT=/tmp/error_report.txt

if [ ! -r "$LOG" ]; then
    echo "Лог не найден или недоступен: $LOG" >&2
    exit 1
fi

# Предполагаем формат combined: IP — первое поле, статус — 9-е поле (после кавычек запроса).
# Используем awk с поиском статуса после закрывающей кавычки запроса для устойчивости.
awk '
{
    # Извлекаем статус: первое трёхзначное число после закрывающей кавычки запроса
    line = $0
    if (match(line, /" [0-9][0-9][0-9] /)) {
        status = substr(line, RSTART + 2, 3)
    } else {
        next
    }
    if ((status ~ /^4[0-9][0-9]$/ || status ~ /^5[0-9][0-9]$/) && status != "404") {
        print $1
    }
}' "$LOG" \
| sort \
| uniq -c \
| awk '{print $1, $2}' \
| sort -k1,1nr -k2,2 \
> "$OUT"

echo "Отчёт сохранён в $OUT"

