OUT="/tmp/error_report.txt"

if [ ! -r "$LOG" ]; then
    echo "Лог-файл $LOG не найден или недоступен для чтения" >&2
    exit 1
fi

# Предполагается формат combined: IP — первое поле, статус — поле 9 (после разделения пробелами)
awk '{
    ip = $1
    status = $9
    if (status ~ /^[0-9]+$/ && ((status >= 400 && status <= 599) && status != 404)) {
        count[ip]++
    }
}
END {
    for (ip in count) print count[ip], ip
}' "$LOG" | sort -k1,1nr -k2,2 > "$OUT"

echo "Отчёт сохранён в $OUT"
